package dev.kelmagic.server;
import dev.kelmagic.*;import dev.kelmagic.core.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.particles.ParticleTypes;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.effect.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.ChestMenu;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.phys.*;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=KelMagic.MODID)
public final class GrandEffects {
 private record Meteor(ServerLevel level,BlockPos at,UUID owner,long impact,double scale){}private static final List<Meteor> METEORS=new ArrayList<>();
 public static boolean execute(ServerPlayer p,SpellParser.Plan plan){String id=plan.actions().getFirst();var aim=SpellEffects.aim(p);boolean ok=switch(id){
 case "wings"->{p.addEffect(new MobEffectInstance(MagicContent.WINGS,SpellProfiles.duration(1200,plan.scale()),0));p.addEffect(new MobEffectInstance(MobEffects.SLOW_FALLING,80));p.setDeltaMovement(p.getDeltaMovement().add(0,.65,0));yield true;}
 case "island"->aim.type()==HitResult.Type.BLOCK&&raiseIsland(p,aim.block().getBlockPos(),plan.scale());
 case "blast"->{var v=aim.point();p.serverLevel().explode(p,v.x,v.y,v.z,(float)(2*plan.scale()),false,Level.ExplosionInteraction.TNT);yield true;}
 case "duplicate"->duplicate(p,aim);
 case "ender"->{p.openMenu(new SimpleMenuProvider((n,inv,who)->ChestMenu.threeRows(n,inv,who.getEnderChestInventory()),Component.translatable("container.enderchest")));yield true;}
 case "mana_tide"->{var target=aim.entity() instanceof ServerPlayer other?other:p;if(target!=p&&!p.canHarmPlayer(target))yield false;target.setData(MagicAttachments.MANA_BOOST_END,target.serverLevel().getGameTime()+1200);target.addEffect(new MobEffectInstance(MagicContent.MANA_TIDE,1200,0));MagicServer.sync(target);yield true;}
 case "meteor"->{if(aim.type()!=HitResult.Type.BLOCK)yield false;if(METEORS.size()>=16)yield false;METEORS.add(new Meteor(p.serverLevel(),aim.block().getBlockPos(),p.getUUID(),p.serverLevel().getGameTime()+40,plan.scale()));yield true;}
 case "transcend"->ascend(p);
 case "threshold_link"->ThresholdLinks.open(p);
 case "grove_awakening"->GroveAwakening.start(p);
 case "end_gate"->{var base=p.blockPosition().relative(p.getDirection(),2);yield WorldSpells.place(p,base,MagicPortals.END_GATE.get().defaultBlockState(),false);}
 default->false;};if(ok&&!id.equals("grove_awakening")&&!id.equals("threshold_link"))MagicProgress.award(p,"rite_"+id);return ok;}
 public static boolean duplicate(ServerPlayer p,SpellEffects.Aim aim){var eye=p.getEyePosition();var end=eye.add(p.getLookAngle().scale(Config.RANGE.get()));Entity source=null;double best=eye.distanceToSqr(aim.block().getLocation());for(var e:p.serverLevel().getEntities(p,new AABB(eye,end).inflate(1),e->e.isAlive()&&!(e instanceof Player)&&!(e instanceof net.minecraft.world.entity.boss.EnderDragonPart))){var hit=e.getBoundingBox().inflate(.15).clip(eye,end);if(hit.isPresent()&&eye.distanceToSqr(hit.get())<best){best=eye.distanceToSqr(hit.get());source=e;}}if(source==null)return false;var clone=source.getType().create(p.serverLevel());if(clone==null)return false;var n=source.saveWithoutId(new CompoundTag());n.remove("UUID");n.remove("Passengers");n.remove("Leash");clone.load(n);clone.setUUID(UUID.randomUUID());clone.moveTo(source.getX()+source.getBbWidth()+.8,source.getY(),source.getZ(),source.getYRot(),source.getXRot());if(!p.serverLevel().hasChunkAt(clone.blockPosition())||!p.serverLevel().getWorldBorder().isWithinBounds(clone.blockPosition())||!p.serverLevel().noCollision(clone))return false;return p.serverLevel().addFreshEntity(clone);}
 public static boolean raiseIsland(ServerPlayer p,BlockPos center,double scale){
  var l=p.serverLevel();int radius=Math.min(8,Math.max(3,(int)Math.round(5*Math.sqrt(scale))));var moved=new LinkedHashMap<BlockPos,BlockState>();var tags=new HashMap<BlockPos,CompoundTag>();int lowest=center.getY(),highest=center.getY();
  for(int x=-radius-1;x<=radius+1;x++)for(int z=-radius-1;z<=radius+1;z++){
   double angle=Math.atan2(z,x),edge=radius*(.87+.10*Math.sin(angle*3+.6)+.08*Math.cos(angle*5));double dist=Math.sqrt(x*x+z*z);if(dist>edge)continue;
   int depth=Math.max(1,(int)Math.round(2+4*(1-dist/edge)+Math.sin(x*1.7+z*.8)));
   for(int y=-depth;y<=32;y++){var at=center.offset(x,y,z);if(!l.isInWorldBounds(at))continue;if(!l.hasChunkAt(at))continue;var s=l.getBlockState(at);if(s.isAir())continue;
    var be=l.getBlockEntity(at);if(be instanceof net.minecraft.world.Container||be instanceof net.minecraft.world.MenuProvider||be!=null&&l.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,at,null)!=null)continue;
    if(s.getDestroySpeed(l,at)<0)continue;if(!moveAllowed(p,at)){KelMagic.LOGGER.debug("Island source denied {}",at);return false;}moved.put(at,s);if(be!=null)tags.put(at,be.saveWithFullMetadata(l.registryAccess()));lowest=Math.min(lowest,at.getY());highest=Math.max(highest,at.getY());
   }
  }
  if(moved.isEmpty()){KelMagic.LOGGER.debug("Island empty");return false;}int lift=Math.max(12,highest-lowest+4);var snapshots=new ArrayList<net.neoforged.neoforge.common.util.BlockSnapshot>();
  for(var at:moved.keySet()){var dest=at.above(lift);if(!moveAllowed(p,dest)||!l.getBlockState(dest).canBeReplaced()||l.getBlockEntity(dest)!=null||!l.getEntities((Entity)null,new AABB(dest),e->e instanceof LivingEntity).isEmpty()){KelMagic.LOGGER.debug("Island destination denied {} state={}",dest,l.getBlockState(dest));return false;}if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(l,at,moved.get(at),p)).isCanceled())return false;snapshots.add(net.neoforged.neoforge.common.util.BlockSnapshot.create(l.dimension(),l,at));snapshots.add(net.neoforged.neoforge.common.util.BlockSnapshot.create(l.dimension(),l,dest));}
  boolean ok=true;for(var at:moved.keySet()){l.removeBlockEntity(at);ok&=l.setBlock(at,Blocks.AIR.defaultBlockState(),18);}for(var entry:moved.entrySet()){var dest=entry.getKey().above(lift);ok&=l.setBlock(dest,entry.getValue(),18);if(tags.containsKey(entry.getKey())){var tag=tags.get(entry.getKey()).copy();tag.putInt("x",dest.getX());tag.putInt("y",dest.getY());tag.putInt("z",dest.getZ());var be=net.minecraft.world.level.block.entity.BlockEntity.loadStatic(dest,entry.getValue(),tag,l.registryAccess());if(be!=null)l.setBlockEntity(be);}}
  for(int i=1;ok&&i<snapshots.size();i+=2)if(net.neoforged.neoforge.event.EventHooks.onBlockPlace(p,snapshots.get(i),Direction.UP))ok=false;
  if(!ok){for(int i=snapshots.size()-1;i>=0;i--)snapshots.get(i).restore();return false;}
  for(var at:moved.keySet()){l.updateNeighborsAt(at,Blocks.AIR);l.updateNeighborsAt(at.above(lift),moved.get(at).getBlock());}l.sendParticles(ParticleTypes.END_ROD,center.getX(),center.getY()+lift,center.getZ(),80,radius,2,radius,.03);return true;
 }
 private static boolean moveAllowed(ServerPlayer p,BlockPos at){var l=p.serverLevel();return !p.isSpectator()&&p.getAbilities().mayBuild&&l.hasChunkAt(at)&&l.isInWorldBounds(at)&&l.getWorldBorder().isWithinBounds(at)&&l.mayInteract(p,at)&&p.mayUseItemAt(at,Direction.UP,p.getMainHandItem());}
 public static boolean ascend(ServerPlayer p){if(p.isSpectator()||p.getData(MagicAttachments.CREATIVE_PREVIOUS)>=0)return false;p.setData(MagicAttachments.CREATIVE_PREVIOUS,p.gameMode.getGameModeForPlayer().getId());p.setData(MagicAttachments.CREATIVE_END,p.serverLevel().getGameTime()+60);p.setGameMode(GameType.CREATIVE);p.addEffect(new MobEffectInstance(MobEffects.GLOWING,60));p.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION,60));p.heal(20);return true;}
 public static void restore(ServerPlayer p,boolean messages){int mode=p.getData(MagicAttachments.CREATIVE_PREVIOUS);if(mode<0)return;p.setData(MagicAttachments.CREATIVE_PREVIOUS,-1);p.setData(MagicAttachments.CREATIVE_END,0L);p.setGameMode(GameType.byId(mode));p.addEffect(new MobEffectInstance(MobEffects.SLOW_FALLING,100));if(messages){p.serverLevel().playSound(null,p.blockPosition(),net.minecraft.sounds.SoundEvents.ENDERMAN_STARE,net.minecraft.sounds.SoundSource.PLAYERS,.8f,.6f);for(String key:List.of("kelmagic.transcend.after1","kelmagic.transcend.after2")){var speaker=Component.literal("???").withStyle(net.minecraft.ChatFormatting.OBFUSCATED,net.minecraft.ChatFormatting.DARK_RED);p.sendSystemMessage(Component.literal("<").withStyle(net.minecraft.ChatFormatting.DARK_RED).append(speaker).append(Component.literal("> ").withStyle(net.minecraft.ChatFormatting.DARK_RED)).append(Component.translatable(key).withStyle(net.minecraft.ChatFormatting.DARK_RED)));}p.serverLevel().setWeatherParameters(0,6000,true,false);for(int i=0;i<2;i++){var at=p.blockPosition().offset(i==0?5:-5,0,i==0?3:-3);at=p.serverLevel().getHeightmapPos(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING,at);if(p.serverLevel().hasChunkAt(at)){var bolt=EntityType.LIGHTNING_BOLT.create(p.serverLevel());if(bolt!=null){bolt.moveTo(Vec3.atBottomCenterOf(at));bolt.setVisualOnly(true);p.serverLevel().addFreshEntity(bolt);}}}}}
 @SubscribeEvent public static void playerTick(net.neoforged.neoforge.event.tick.PlayerTickEvent.Post e){if(!(e.getEntity() instanceof ServerPlayer p))return;if(p.getData(MagicAttachments.CREATIVE_PREVIOUS)>=0){if(!p.isAlive()||p.serverLevel().getGameTime()>=p.getData(MagicAttachments.CREATIVE_END)){restore(p,true);return;}if(p.tickCount%5==0)for(int y=0;y<96;y+=4)if(p.getY()+y<p.level().getMaxBuildHeight())p.serverLevel().sendParticles(ParticleTypes.END_ROD,p.getX(),p.getY()+y,p.getZ(),3,.08,.2,.08,.01);}}
 @SubscribeEvent public static void login(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent e){if(e.getEntity() instanceof ServerPlayer p)restore(p,false);}
 @SubscribeEvent public static void logout(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent e){if(e.getEntity() instanceof ServerPlayer p)restore(p,false);}
 @SubscribeEvent public static void serverTick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){for(var it=METEORS.iterator();it.hasNext();){var m=it.next();if(m.level.getServer()!=e.getServer()){it.remove();continue;}long remain=m.impact-m.level.getGameTime();if(!m.level.hasChunkAt(m.at)){it.remove();continue;}if(remain<=0){var caster=m.level.getServer().getPlayerList().getPlayer(m.owner);m.level.explode(caster,m.at.getX()+.5,m.at.getY()+1,m.at.getZ()+.5,(float)(6*Math.sqrt(m.scale)),true,Level.ExplosionInteraction.TNT);it.remove();}else m.level.sendParticles(ParticleTypes.FLAME,m.at.getX()+.5,m.at.getY()+remain*.7,m.at.getZ()+.5,18,.8,.8,.8,.06);}}
 @SubscribeEvent public static void stop(net.neoforged.neoforge.event.server.ServerStoppingEvent e){for(var p:e.getServer().getPlayerList().getPlayers())restore(p,false);METEORS.clear();}
}